<script setup lang="ts">
import { useDemoStore } from '~/stores/demo'
import { useSessionStore } from '~/stores/session'
definePageMeta({layout:'workspace'});import{selectHierarchy}from'~/demo/selectors.mjs';const demo=useDemoStore(),session=useSessionStore();const tree=computed(()=>selectHierarchy(demo.data,session.session||{}));const name=ref('');const selectedOrg=ref('');const selectedNetwork=ref('');function createOrg(){demo.run({type:'hierarchy:create-organization',name:name.value},session.session||{});name.value=''}function createNetwork(){demo.run({type:'hierarchy:create-network',organizationId:selectedOrg.value,name:name.value},session.session||{});name.value=''}function assign(channelId:string){if(selectedNetwork.value)demo.run({type:'hierarchy:assign-channel',channelId,networkId:selectedNetwork.value},session.session||{})}</script>
<template><div class="page-content"><div class="page-title-row"><div><span class="page-label">NETWORK MANAGEMENT</span><h1>Network hierarchy</h1><p>View the platform, organization, MCN and creator channel structure.</p></div><span class="tag tag-muted">{{session.session?.role==='admin'?'PLATFORM VIEW':'SCOPED VIEW'}}</span></div><div v-for="org in tree" :key="org.id" class="hierarchy-org"><div class="hierarchy-org-head"><div><strong>{{org.name}}</strong><div class="secondary-text">{{org.city || "Location not listed"}} · {{org.status}}</div></div><span class="tag">{{org.networks.length}} networks</span></div><div v-for="net in org.networks" :key="net.id" class="hierarchy-network"><strong>{{net.name}} <span class="secondary-text">· {{net.channels.length}} YouTube channels</span></strong><div class="channel-pills"><span v-for="c in net.channels" :key="c.id" class="channel-pill">{{c.title}}</span></div></div></div><section v-if="session.session?.role==='admin'" class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Manage the sample hierarchy</h2><p>Local demo changes only</p></div><span class="tag tag-violet">SUPER ADMIN</span></div><div class="panel-body"><form class="filter-row" @submit.prevent="createOrg"><input v-model="name" class="filter-field" placeholder="New organization name" required><button class="button button-outline button-small">＋ Organization</button></form><form class="filter-row" @submit.prevent="createNetwork"><select v-model="selectedOrg" class="filter-field" required><option value="">Choose organization</option><option v-for="o in demo.data.organizations" :key="o.id" :value="o.id">{{o.name}}</option></select><input v-model="name" class="filter-field" placeholder="New network name" required><button class="button button-outline button-small">＋ Network</button></form><div class="filter-row"><select v-model="selectedNetwork" class="filter-field"><option value="">Choose network for channel assignment</option><option v-for="n in demo.data.networks" :key="n.id" :value="n.id">{{n.name}}</option></select><select class="filter-field" @change="assign(($event.target as HTMLSelectElement).value)"><option value="">Assign channel…</option><option v-for="c in demo.data.channels" :key="c.id" :value="c.id">{{c.title}}</option></select></div></div></section><section v-else class="panel"><div class="panel-body"><strong>Your view follows your current role.</strong><p class="secondary-text">Admin can edit sample organizations, networks and channel assignments. Switch role from the profile menu to inspect another view.</p></div></section></div></template>
